#!/usr/bin/env python3
"""External validation on CLEF TAR 2019 (see PLAN.md): every number in external/results.md. No API calls.

  evaluate.py [--condition full|objectives] [--check]     writes results.md (full) or results-<condition>.md

Thresholds come from benchmark/calibration.json (frozen on SYNERGY+) plus the corrected 100% one; nothing is tuned here.
Product rule: a record without an abstract, or not found in PubMed, is never below the threshold. Sampled records are
weighted back to each review's size for every share of records; recall counts every include (none is sampled out)."""
import json
import statistics
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
import clef
import common

from sievesafe import MODEL

HERE = Path(__file__).resolve().parent
CONDITION = sys.argv[sys.argv.index("--condition") + 1] if "--condition" in sys.argv else "full"
OUT = HERE / ("results.md" if CONDITION == "full" else f"results-{CONDITION}.md")
VARIANT = clef.CONDITIONS[CONDITION]["variant"]
info = clef.reviews(CONDITION)
TASK_DIR, TASK_LABEL, _ = clef.TASKS[clef.CONDITIONS[CONDITION]["task"]]
N_REV = len(info["reviews"])
ABS_OK = clef.CONDITIONS[CONDITION].get("keep", "either") == "either"  # title/abstract includes kept whole, so their recall is exact
frozen = {k: v["threshold"] for k, v in json.loads(common.CALIBRATION.read_text())["targets"].items()}
SAFE, CORR = frozen["100%"], common.calibrate()["targets"]["100%"]["threshold"]
THRESHOLDS = [(SAFE, "safe, frozen"), (CORR, "safe, corrected"), (frozen["98%"], "98%, frozen"), (frozen["95%"], "95%, frozen")]
pct = lambda x: f"{x:.0%}"
pct1 = lambda x: f"{x:.1%}"

reviews = {}
for topic in info["reviews"]:
    s = common.answers(VARIANT, topic)
    rows = [{"pmid": r["pmid"], "y": int(r["y"]), "ya": int(r["ya"]), "w": r["w"], "abstract": bool(r["abstract"]), "s": s.get(r["pmid"])}
            for r in clef.rows(topic, info["reviews"][topic], CONDITION)]
    missing = [r["pmid"] for r in rows if r["s"] is None and r["abstract"]]
    if missing:
        sys.exit(f"{topic}: {len(missing)} records with an abstract have no answer yet; run external/screen.py --condition {CONDITION}")
    reviews[topic] = rows


def below(r: dict, t: float, rule: bool = True) -> bool:
    return r["s"] is not None and r["s"] < t and (r["abstract"] or not rule)


def recall(rows: list[dict], t: float, label: str = "y", rule: bool = True) -> float | None:
    P = sum(r[label] for r in rows)
    return sum(r[label] for r in rows if not below(r, t, rule)) / P if P else None


def share_below(rows: list[dict], t: float) -> float:
    return sum(r["w"] for r in rows if below(r, t)) / sum(r["w"] for r in rows)


def wss(rows: list[dict], target: float) -> float:
    """Weighted WSS: reading in score order (unscored first), share of the review's records not read when `target` is found."""
    order = sorted(rows, key=lambda r: -(r["s"] if r["s"] is not None else 2.0))
    W, need, found, read = sum(r["w"] for r in rows), -(-target * sum(r["y"] for r in rows) // 1), 0, 0.0
    for r in order:
        found += r["y"]
        read += r["w"]
        if found >= need:
            return (W - read) / W - (1 - target)
    return float("nan")


def wauc(rows: list[dict]) -> float:
    pos = [r["s"] if r["s"] is not None else 2.0 for r in rows if r["y"]]
    neg = [(r["s"] if r["s"] is not None else 2.0, r["w"]) for r in rows if not r["y"]]
    return sum(w * ((p > n) + 0.5 * (p == n)) for p in pos for n, w in neg) / (len(pos) * sum(w for _, w in neg))


with_inc = {k: v for k, v in reviews.items() if sum(r["y"] for r in v)}
pooled = [r for v in reviews.values() for r in v]
P = sum(r["y"] for r in pooled)
calls = common.calls(VARIANT)
tok = sum(c["usage"]["input_tokens"] for c in calls)
L = [f"# External validation: CLEF TAR 2019 ({TASK_LABEL}, {N_REV} Cochrane reviews)" + ("" if CONDITION == "full" else f" — criteria: {clef.CONDITIONS[CONDITION]['criteria']}"), "",
     "Generated by `benchmark/external/evaluate.py`; plan fixed beforehand in `PLAN.md`. Do not edit by hand.", "",
     (f"- CLEF TAR commit `{info['clef_commit'][:12]}`; up to {info['cap']:,} records per review (every include kept, the rest a weighted sample)"
      if CONDITION == "full" else f"- CLEF TAR commit `{info['clef_commit'][:12]}`; every include plus up to {clef.CONDITIONS[CONDITION]['others'] or info['others']} "
      + ("other records per review (a subset of the full-criteria sample, weighted to the review's size)"
         if clef.CONDITIONS[CONDITION]["task"] == clef.CONDITIONS["full"]["task"] else "other records per review (a seeded sample, weighted to the review's size)")),
     (f"- {sum(m['records_total'] for m in info['reviews'].values()):,} records in the {N_REV} reviews, {len(pooled):,} asked, {P} final includes "
      + (f"({sum(r['ya'] for r in pooled)} title/abstract includes)" if ABS_OK else "(only final includes kept whole)")
      + f"; {len(with_inc)} reviews have at least one final include"),
     f"- Thresholds from SYNERGY+, not retuned: {', '.join(f'{t} ({n})' for t, n in THRESHOLDS)}",
     (f"- Model {MODEL}, {len(calls):,} calls, US$ {tok * common.PRICE_PER_TOKEN:.3f}; answers sha256 "
      f"`{common.answers_sha(VARIANT)[:12]}`"),
     (f"- Records without an abstract or not in PubMed (never below the threshold): {sum(not r['abstract'] for r in pooled)} asked records, "
      f"{sum(r['y'] and not r['abstract'] for r in pooled)} of them final includes"), ""]

L += ["## Primary endpoint (threshold 0.06, product rule)", "",
      "| review | records | asked | final includes | kept | records below (weighted) | title/abstract includes kept |", "|:--|--:|--:|--:|--:|--:|--:|"]
for k, v in reviews.items():
    m = info["reviews"][k]
    rec = recall(v, SAFE)
    L.append(f"| {k} | {m['records_total']:,} | {len(v):,} | {m['includes']} | {'—' if rec is None else pct(rec)} | {pct(share_below(v, SAFE))} | "
             f"{'—' if not ABS_OK or recall(v, SAFE, 'ya') is None else pct(recall(v, SAFE, 'ya'))} |")
L.append("")
summary = []
for t, name in THRESHOLDS:
    recs = [recall(v, t) for v in with_inc.values()]
    summary.append([f"{t} ({name})", f"{sum(r == 1 for r in recs)}/{len(recs)}", f"{sum(r >= 0.98 for r in recs)}/{len(recs)}",
                    f"{sum(r >= 0.95 for r in recs)}/{len(recs)}", pct(min(recs)), pct1(recall(pooled, t)),
                    pct(sum(r["w"] for r in pooled if below(r, t)) / sum(r["w"] for r in pooled)),
                    pct(statistics.mean(share_below(v, t) for v in reviews.values()))])
L += ["| threshold | reviews keeping every include | reviews ≥98% | reviews ≥95% | lowest review | pooled recall | records below (pooled, weighted) | records below (mean per review) |",
      "|:--|--:|--:|--:|--:|--:|--:|--:|", *("| " + " | ".join(r) + " |" for r in summary), ""]
ok = all(recall(v, SAFE) >= 0.98 for v in with_inc.values())
L += [(f"**Pre-specified verdict: {'successful external validation' if ok else 'failure'}** — "
       f"{'every' if ok else 'not every'} review with an include kept at least 98% of its final includes at {SAFE}."), ""]

lost = [(k, r) for k, v in with_inc.items() for r in v if r["y"] and below(r, SAFE)]
L += ["## Secondary", "",
      (f"- Score alone (no abstract rule) at {SAFE}: pooled recall {pct1(recall(pooled, SAFE, rule=False))}, "
       f"reviews keeping every include {sum(recall(v, SAFE, rule=False) == 1 for v in with_inc.values())}/{len(with_inc)}"),
      (f"- Title/abstract includes kept at {SAFE}: {pct1(recall(pooled, SAFE, 'ya'))} pooled, lowest review "
       f"{pct(min(recall(v, SAFE, 'ya') for v in reviews.values() if recall(v, SAFE, 'ya') is not None))}"
       if ABS_OK else "- Title/abstract includes: not measured (only final includes were kept whole in this set)"),
      (f"- Ranking (weighted): median WSS@95 {statistics.median(wss(v, 0.95) for v in with_inc.values()):.3f}, "
       f"median WSS@100 {statistics.median(wss(v, 1.0) for v in with_inc.values()):.3f}, median AUC {statistics.median(wauc(v) for v in with_inc.values()):.3f}"),
      f"- Final includes below {SAFE}: {len(lost)}" + ("" if not lost else " — " + ", ".join(f"{k} PMID {r['pmid']} (score {r['s']})" for k, r in lost)), ""]
if CONDITION != "full" and clef.CONDITIONS[CONDITION]["task"] == clef.CONDITIONS["full"]["task"]:
    base = {k: common.answers(clef.CONDITIONS["full"]["variant"], k) for k in reviews}
    pairs = [(base[k][r["pmid"]], r["s"], r) for k, v in reviews.items() for r in v if r["s"] is not None and r["pmid"] in base[k]]
    a_, b_ = [x for x, _, _ in pairs], [y for _, y, _ in pairs]
    ma, mb = statistics.mean(a_), statistics.mean(b_)
    corr = sum((x - ma) * (y - mb) for x, y in zip(a_, b_)) / (sum((x - ma) ** 2 for x in a_) * sum((y - mb) ** 2 for y in b_)) ** 0.5
    dropped = [r for x, y, r in pairs if r["y"] and x >= SAFE > y]
    L += ["## Paired with the full criteria (same records)", "",
          f"- {len(pairs):,} records scored under both: correlation {corr:.3f}; mean score {mb:.3f} here vs {ma:.3f} with full criteria",
          f"- Final includes at or above {SAFE} with full criteria but below it here: {len(dropped)}",
          f"- Records below {SAFE} (unweighted, same records): {sum(y < SAFE for y in b_) / len(b_):.0%} here vs {sum(x < SAFE for x in a_) / len(a_):.0%} with full criteria", ""]
L += ["## Criteria sources", "", "| review | criteria from | selection criteria section |", "|:--|:--|:--|",
      *(f"| {k} | {m['doi']} ({m['year']}) | {'yes' if m['has_selection_criteria'] else 'no'} |" for k, m in info["reviews"].items()), ""]

text = "\n".join(L)
fails = sum(recall(v, SAFE) < 1 for v in with_inc.values())
summary = {"set": f"{TASK_LABEL} ({len(reviews)} reviews)", "criteria": clef.CONDITIONS[CONDITION]["criteria"], "reviews": len(reviews), "reviews_with_includes": len(with_inc),
           "reviews_keeping_all": len(with_inc) - fails, "includes": P, "includes_kept": sum(r["y"] for r in pooled if not below(r, SAFE)),
           "records_below": round(sum(r["w"] for r in pooled if below(r, SAFE)) / sum(r["w"] for r in pooled), 4),
           "upper_bound_reviews_losing": round(common.cp_upper(fails, len(with_inc)), 4)}
SUMMARY = HERE / f"summary-{CONDITION}.json"
summaries = {c: json.loads((HERE / f"summary-{c}.json").read_text()) for c in clef.CONDITIONS if (HERE / f"summary-{c}.json").exists()}
summaries[CONDITION] = summary
S = [summaries[c] for c in clef.CONDITIONS if c in summaries]
START, END = "<!-- external:start (generated by benchmark/external/evaluate.py) -->", "<!-- external:end -->"
block = "\n".join([START, "", f"| CLEF TAR 2019 Cochrane reviews, pre-registered, threshold {SAFE} unchanged | "
                    + " | ".join(f"{s['set']}, criteria: {s['criteria']}" for s in S) + " |", "|:--|" + "--:|" * len(S),
                    "| reviews keeping every finally included study | " + " | ".join(f"{s['reviews_keeping_all']}/{s['reviews_with_includes']}" for s in S) + " |",
                    "| finally included studies kept | " + " | ".join(f"{s['includes_kept']} of {s['includes']}" for s in S) + " |",
                    "| records below the threshold (weighted) | " + " | ".join(pct(s["records_below"]) for s in S) + " |",
                    "| 95% upper bound on reviews losing any include | " + " | ".join(pct(s["upper_bound_reviews_losing"]) for s in S) + " |", "", END])
README = common.HERE.parent / "README.md"
readme = README.read_text()
if START not in readme or END not in readme:
    sys.exit(f"README.md has no {START} … {END} block")
readme = readme[:readme.index(START)] + block + readme[readme.index(END) + len(END):]
summary_text = json.dumps(summary, indent=1) + "\n"
if "--check" in sys.argv:
    stale = [f.name for f, x in ((OUT, text), (SUMMARY, summary_text), (README, readme)) if not f.exists() or f.read_text() != x]
    sys.exit(f"stale: {', '.join(stale)}; run external/evaluate.py --condition {CONDITION}" if stale else 0)
OUT.write_text(text)
SUMMARY.write_text(summary_text)
README.write_text(readme)
print(f"wrote {OUT.relative_to(common.HERE.parent)}, {SUMMARY.name} and the external block of README.md")
